<?php
declare(strict_types=1);
require_once __DIR__ . '/../app/bootstrap.php';
use BAJAMA\Core\Auth; use BAJAMA\Core\License; use BAJAMA\Core\RBAC; use BAJAMA\Core\Tenant; use BAJAMA\Network\MikroTik; use BAJAMA\Network\RouterOsLiveData;
Auth::requireLogin(); $db=db(); License::requireFeature($db,'mikrotik'); RBAC::require($db,'mikrotik.view'); $org=(int)Tenant::id(); $routers=MikroTik::all($db,$org); $routerId=(int)($_GET['router_id']??($routers[0]['id']??0)); $error='';$data=[];try{if($routerId>0)$data=RouterOsLiveData::read($db,$org,$routerId);}catch(Throwable $e){$error=$e->getMessage();} $interfaces=[];foreach(($data['interfaces']??[]) as $r){$n=trim((string)($r['name']??''));if($n!=='')$interfaces[]=$n;} $ip=trim((string)($_GET['ip']??''));$gateway=trim((string)($_GET['gateway']??''));$source=trim((string)($_GET['source']??($interfaces[0]??'')));$destination=trim((string)($_GET['destination']??($interfaces[1]??'')));$script=$ip!==''&&$gateway!==''&&$source!==''&&$destination!==''?"/ip/route\nadd dst-address={$ip} gateway={$gateway}%{$source} comment=BAJAMA:LOADBALANCE\n/ip/firewall/mangle\nadd chain=prerouting in-interface={$source} action=mark-routing new-routing-mark=BAJAMA-LB-{$destination} passthrough=no comment=BAJAMA:LOADBALANCE\n":'';function lbp_h($v):string{return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}$pageTitle='Load Balance';ob_start();?><div class="container-fluid py-4"><h1 class="fw-bold">Load Balance</h1><p class="text-muted">Isi IP address, gateway, interface sumber, dan interface tujuan berdasarkan data live MikroTik.</p><?php if($error):?><div class="alert alert-danger"><?=lbp_h($error)?></div><?php endif;?><form class="card border-0 shadow-sm p-4 mb-4"><input type="hidden" name="router_id" value="<?=$routerId?>"><div class="row g-3"><div class="col-md-3"><label class="form-label">IP address tujuan</label><input name="ip" class="form-control" value="<?=lbp_h($ip)?>" placeholder="203.0.113.0/24"></div><div class="col-md-3"><label class="form-label">IP gateway</label><input name="gateway" class="form-control" value="<?=lbp_h($gateway)?>" placeholder="192.168.1.1"></div><div class="col-md-2"><label class="form-label">Interface sumber</label><select name="source" class="form-select"><?php foreach($interfaces as $i):?><option <?=$source===$i?'selected':''?>><?=lbp_h($i)?></option><?php endforeach;?></select></div><div class="col-md-2"><label class="form-label">Interface tujuan</label><select name="destination" class="form-select"><?php foreach($interfaces as $i):?><option <?=$destination===$i?'selected':''?>><?=lbp_h($i)?></option><?php endforeach;?></select></div><div class="col-md-2 d-flex align-items-end"><button class="btn btn-primary w-100">Buat Script</button></div></div></form><div class="card border-0 shadow-sm p-4"><h2 class="h5">Script RouterOS</h2><textarea class="form-control" rows="8" readonly><?=lbp_h($script)?></textarea></div></div><?php $content=ob_get_clean();require __DIR__.'/../app/layout/layout.php';
